import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingTagRulesList } from '../../generated/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueTagRuleKeysLogicValues {
    issueTagRuleKeys: string[] | null
    issueTagRuleKeysLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueTagRuleKeysLogicActions {
    loadIssueTagRuleKeys: () => any
    loadIssueTagRuleKeysFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadIssueTagRuleKeysSuccess: (
        issueTagRuleKeys: string[],
        payload?: any
    ) => {
        issueTagRuleKeys: string[]
        payload?: any
    }
}

export type issueTagRuleKeysLogicType = MakeLogicType<issueTagRuleKeysLogicValues, issueTagRuleKeysLogicActions>

// The tag definitions do not say which tags a rule applies, so the keys come from the tag rules.
export const issueTagRuleKeysLogic = kea<issueTagRuleKeysLogicType>([
    path(['products', 'error_tracking', 'components', 'IssueTagsButton', 'issueTagRuleKeysLogic']),

    loaders(() => ({
        issueTagRuleKeys: [
            null as string[] | null,
            {
                loadIssueTagRuleKeys: async () => {
                    const { results } = await errorTrackingTagRulesList(String(teamLogic.values.currentTeamId))
                    return results.map((rule) => rule.key)
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadIssueTagRuleKeys()
    }),
])
